Hi, I'm facing a problem with version 0.2.4.
After some debug I found that sometimes blobs become empty after the checkpoint.
In my test I forced a checkpoint closing and reloading the DB in READ_WRITE mode.
Here is a simple program to see the problem:

````C++
#include <iostream>
#include "duckdb.hpp"
#include "duckdb/main/appender.hpp"

using namespace duckdb;

int main(int argc, char *argv[])
{
        DBConfig config;
	config.access_mode = AccessMode::READ_WRITE;

	{
		std::cout << "Creating TestBlob.duck...";
		DuckDB dbObj("TestBlob.duck", &config);
		Connection conObj(dbObj);
		std::cout << " Ok" << std::endl;

		conObj.Query("CREATE TABLE test(value BLOB);");

		unsigned char data[] = { 128, 230, 197, 71, '\0' };
		unsigned char data2[] = { 'C', 'I', 'A', '0', '\0' };

		conObj.BeginTransaction();
		{
			std::cout << "Appending data to test table" << std::endl;

			Appender appender(conObj, "test");

			appender.BeginRow();
			appender.Append(Value::BLOB((const_data_ptr_t)data, 4));
			appender.EndRow();

			appender.BeginRow();
			appender.Append(Value::BLOB((const_data_ptr_t)data2, 4));
			appender.EndRow();

			appender.Flush();
		}
		conObj.Commit();

		std::cout << "Reading test table" << std::endl;

		auto result = conObj.Query("SELECT * FROM test");

		result->Print();
	}

	{
		std::cout << "Execute checkpoint...";
		DuckDB dbObj("TestBlob.duck", &config);
		Connection conObj(dbObj);
		std::cout << " Ok" << std::endl;

		std::cout << "Reading test table" << std::endl;

		auto result = conObj.Query("SELECT * FROM test");

		result->Print();
	}
	return 0;
}
````

Output:

````
Creating TestBlob.duck... Ok
Appending data to test table
Reading test table
value
BLOB
[ Rows: 2]
\x80\xE6\xC5G
CIA0


Execute checkpoint... Ok
Reading test table
value
BLOB
[ Rows: 2]
NULL
CIA0
````

# Bug Report

### 🔎 Search Terms

implicitly any, key remapping, filter object properties by type

### ⏯ Playground Link

